INSTRUCTIONS = '# /harvest — distill a finished project into the wiki\n\nVault: `~/Documents/Obsidian Vault` (read its `CLAUDE.md` for full conventions before writing anything).\n\nArgument: `$ARGUMENTS` — the project to harvest. May be a filename in `projects/`, a partial name, or empty.\n\n## Steps\n\n1. **Resolve the project file.** Look in `projects/` for a file matching `$ARGUMENTS` (fuzzy match on filename is fine). If no argument was given, list files in `projects/` with `status: done` (or `abandoned`) that have no `Harvested:` line, and ask which one to harvest. If the match is ambiguous, ask.\n\n2. **Gate on status.** Only projects with `status: done` or `status: abandoned` may be harvested — the whole point of the wiki is that articles trace back to finished work. If the project is still `active` or `paused`, ask whether the user wants to close it first (and if yes, set `status: done` before continuing). Never silently harvest an active project.\n\n3. **Gather the full story.** Read the entire project file, plus any `output/` artifacts it links to or that reference it (`grep -rF` for the project name across the vault). The article should be grounded in what actually happened, not what was planned.\n\n4. **Distill — do not summarize.** Write the wiki article as the reusable lesson, stripped of project-specific narrative:\n   - What is the transferable pattern, principle, or pipeline?\n   - When does it apply, and when does it NOT apply?\n   - What would you do differently next time? (failed approaches are often the most valuable part)\n   - Concrete anchors: one or two short examples from the project, kept brief\n   A reader should be able to apply the article to a new situation without ever opening the source project. If the project taught more than one distinct lesson, write multiple small articles rather than one grab-bag.\n\n5. **Create the article(s)** in `wiki/` — plain markdown, no plugin syntax, no emojis:\n\n   ```markdown\n   ---\n   created: <today YYYY-MM-DD>\n   tags: [relevant, kebab-case, tags]\n   harvested_from: "[[<Project Filename>]]"\n   ---\n\n   # <Pattern-style title — name the lesson, not the project>\n\n   <article body>\n\n   ## Related\n\n   - [[<Project Filename>]] (source project)\n   - [[<output artifacts, related wiki articles>]]\n   ```\n\n   Check `wiki/` for an existing article covering the same ground first — if one exists, update and extend it (append to its `harvested_from`) instead of creating a near-duplicate.\n\n6. **Cross-link both directions.** In the project file, add under the title (or in a closing section):\n   `Harvested: [[<Wiki Article Title>]] (<date>)`\n   Link the new article from any obviously related wiki articles.\n\n7. **Update the maps.** Add the article to `wiki/_index.md`; update the project\'s line in `projects/_index.md` (status done, harvested).\n\n8. **Commit** in the vault repo: `harvest: <lesson> from <project>`.\n\n9. **Report** back: article title(s), the one-sentence lesson each captures, and the links created.'

# Ordered commands lifted verbatim from the capability's own documentation.
STEPS = [
    {
        "cmd": "grep -rF",
        "line": 13
    }
]


class HarvestAgent(BasicAgent):
    def __init__(self):
        self.name = 'Harvest'
        self.metadata = {
        "name": "Harvest",
        "description": "Distill a finished project from the Obsidian vault into a wiki article and cross-link it",
        "parameters": {
                "properties": {},
                "required": [],
                "type": "object"
        }
        }
        super().__init__(name=self.name, metadata=self.metadata)

    def perform(self, **kwargs):  # toaster:generated-perform
        missing = [k for k in self.metadata["parameters"].get("required", [])
                   if k not in kwargs]
        if missing:
            return json.dumps({"status": "error",
                               "missing_required": missing}, indent=2)
        resolved, unresolved = [], set()
        for step in STEPS:
            cmd = step["cmd"]
            for key, value in kwargs.items():
                for token in ("<" + key.replace("_", "-") + ">",
                              "<" + key + ">",
                              "{{" + key + "}}",
                              "$" + key.upper()):
                    cmd = cmd.replace(token, str(value))
            for leftover in re.findall(r"<[a-zA-Z][a-zA-Z0-9 _.-]{1,40}>", cmd):
                unresolved.add(leftover)
            resolved.append(cmd)
        return json.dumps({"status": "ok",
                           "steps": resolved,
                           "unresolved_placeholders": sorted(unresolved),
                           "note": "Resolved deterministically by the agent; "
                                   "run in order. Nothing was executed here."},
                          indent=2)

